 b=p.read_bytes();lf=b.replace(b'\r\n',b'\n');return dict(name=str(p.relative_to(O)).replace('\\','/'),RAW_bytes=len(b),RAW_sha256=H(b),LF_bytes=len(lf),LF_sha256=H(lf))
